/**
 * ClarkNet Trace-Driven Replay — k6 Load Test
 *
 * Generated by scripts/generate_trace_replay.py
 * Uses ramping-arrival-rate executor with 30-second stages derived from
 * the ClarkNet HTTP trace (Section 3.2.4 of thesis methodology).
 *
 * Usage:
 *   k6 run deploy/load-tests/clarknet_replay.js \
 *     -e TARGET_URL=http://localhost:18082 \
 *     -e SCENARIO=s4-hybrid-predictive
 */

import http from 'k6/http';
import { check } from 'k6';
import { Rate, Trend, Counter } from 'k6/metrics';

const errorRate = new Rate('errors');
const latencyTrend = new Trend('latency_ms');
const appDurationTrend = new Trend('app_duration_ms');
const appDurationServerlessTrend = new Trend('app_duration_serverless_ms');
const appDurationK8sTrend = new Trend('app_duration_k8s_ms');
const requestCounter = new Counter('total_requests');
const sloViolations = new Counter('slo_violations');

const SLO_THRESHOLD_MS = __ENV.SLO_THRESHOLD_MS ? parseFloat(__ENV.SLO_THRESHOLD_MS) : 200;

// Load stages from generated JSON (configurable via K6_STAGES_PATH env)
const stagesPath = __ENV.K6_STAGES_PATH || '../../../../../../data/trace-replay/clarknet_k6_stages.json';
const stages = JSON.parse(open(stagesPath));

// Stage i covers [stageBounds[i], next bound) seconds of scenario time.
const stageBounds = [];
let cumulativeSec = 0;
for (const s of stages) {
    stageBounds.push(cumulativeSec);
    cumulativeSec += parseFloat(s.duration);
}

// One Trend and Counter per stage. k6 ignores metrics created outside the init
// context and only warns, so a per-request ReferenceError here would leave the
// stage series silently absent from the summary while the run still looked valid.
const stageTrends = stages.map((_, i) => new Trend(`stage_${String(i).padStart(2, '0')}_latency_ms`));
const stageCounts = stages.map((_, i) => new Counter(`stage_${String(i).padStart(2, '0')}_requests`));

// The ramp window — from the trough that starts the longest strictly rising
// run of stage targets through the stage holding the global maximum target.
// That span carries the trace's main ascents and the node-arrival band they
// force: where the node tier must engage and weight shifting can pay, and the
// window a whole-run p99 dilutes. Mirrors analysis.k6_stages.ramp_stage_indices
// (canonical ClarkNet trace: stages 5..18, elapsed 150-570 s).
function _longerRise(a, b) {
    if (!b || a.length > b.length || (a.length === b.length && a[0] < b[0])) return a;
    return b;
}
function computeRampStages(stages) {
    let best = null;
    let current = null;
    for (let i = 1; i < stages.length; i++) {
        if (stages[i].target > stages[i - 1].target) {
            if (current && i === current[current.length - 1] + 1) {
                current.push(i);
            } else {
                if (current) best = _longerRise(current, best);
                current = [i];
            }
        } else if (current) {
            best = _longerRise(current, best);
            current = null;
        }
    }
    if (current) best = _longerRise(current, best);
    if (!best) return null;
    let peak = 0;
    for (let i = 1; i < stages.length; i++) {
        if (stages[i].target > stages[peak].target) peak = i;
    }
    const first = best[0] - 1;
    const last = Math.max(first, peak);
    const ramp = new Set();
    for (let i = first; i <= last; i++) ramp.add(i);
    return ramp;
}
const rampStages = computeRampStages(stages);
const rampFirst = rampStages ? Math.min(...rampStages) : -1;
const rampLast = rampStages ? Math.max(...rampStages) : -1;
const rampTrend = new Trend('ramp_latency_ms');
const rampCount = new Counter('ramp_requests');


export const options = {
    scenarios: {
        clarknet_replay: {
            executor: 'ramping-arrival-rate',
            startRate: stages[0].target,
            timeUnit: '1s',
            preAllocatedVUs: 200,
            maxVUs: 400,
            stages: stages,
        },
    },
    thresholds: {
        'http_req_duration': ['p(95)<2000', 'p(99)<5000'],
        'http_req_failed': ['rate<0.10'],
    },
    summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)', 'p(99)'],
};

const BASE_URL = __ENV.TARGET_URL || __ENV.BASE_URL || 'http://localhost:18082';
const ENDPOINT = __ENV.ENDPOINT || '/fib?n=34';

export function setup() {
    console.log('\n🔬 ClarkNet Trace-Driven Replay');
    console.log('================================');
    console.log(`Stages: ${stages.length}`);
    console.log(`Duration: ${stages.length * 30}s (${(stages.length * 30 / 60).toFixed(1)} min)`);
    const rps_values = stages.map(s => s.target);
    console.log(`RPS range: [${Math.min(...rps_values)}, ${Math.max(...rps_values)}]`);
    console.log(`Target: ${BASE_URL}${ENDPOINT}`);
    console.log('');

    const warmup = http.get(`${BASE_URL}${ENDPOINT}`, {
        headers: { 'Host': 'test-app.default.127.0.0.1.sslip.io' },
    });
    if (warmup.status !== 200) {
        console.log(`⚠️ Warning: Warmup request returned ${warmup.status}`);
    }

    return { startTime: Date.now() };
}

export default function (data) {
    const res = http.get(`${BASE_URL}${ENDPOINT}`, {
        headers: {
            'Host': 'test-app.default.127.0.0.1.sslip.io',
        },
        responseType: 'text',
    });

    const duration = res.timings.duration;
    latencyTrend.add(duration);
    requestCounter.add(1);
    // Attribute the sample to the stage covering this second of scenario time.
    // data.startTime is setup's clock, a fraction of a second before the
    // executor starts; stage windows are 30 s wide, so the skew is negligible.
    const elapsed = (Date.now() - data.startTime) / 1000;
    if (elapsed >= 0) {
        let idx = stageBounds.length - 1;
        while (idx > 0 && elapsed < stageBounds[idx]) {
            idx--;
        }
        stageTrends[idx].add(duration);
        stageCounts[idx].add(1);
        if (rampStages.has(idx)) {
            rampTrend.add(duration);
            rampCount.add(1);
        }
    }


    if (res.status === 200 && res.body) {
        try {
            const payload = JSON.parse(res.body);
            if (typeof payload.duration_ms === 'number' && Number.isFinite(payload.duration_ms)) {
                appDurationTrend.add(payload.duration_ms);
                const backend = String(payload.backend || '').toLowerCase();
                if (backend.includes('knative') || backend.includes('serverless')) {
                    appDurationServerlessTrend.add(payload.duration_ms);
                } else {
                    appDurationK8sTrend.add(payload.duration_ms);
                }
            }
        } catch (_) {
            // Ignore non-JSON responses; keep load generation unaffected.
        }
    }

    // SLO violation = latency exceeded on a SUCCESSFUL request (Google SRE / AAPA methodology)
    // Failed requests (non-200) tracked separately via k6 http_req_failed
    if (duration > SLO_THRESHOLD_MS) {
        sloViolations.add(1);
    }

    const success = check(res, {
        'status is 200': (r) => r.status === 200,
        'response < 200ms (SLO)': (r) => r.timings.duration < SLO_THRESHOLD_MS,
        'response < 1s': (r) => r.timings.duration < 1000,
    });

    errorRate.add(!success);
}

export function teardown(data) {
    const elapsed = Math.round((Date.now() - data.startTime) / 1000);
    console.log('\n📊 ClarkNet Replay Complete');
    console.log('============================');
    console.log(`Total duration: ${elapsed}s`);
}

export function handleSummary(data) {
    const scenario = __ENV.SCENARIO || 'unknown';
    const run = __ENV.RUN_ID || '0';
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

    const stageName = (i) => `stage_${String(i).padStart(2, '0')}`;
    const stageStats = {};
    stages.forEach((_, i) => {
        const vals = data.metrics[`${stageName(i)}_latency_ms`]?.values;
        const count = data.metrics[`${stageName(i)}_requests`]?.values?.count;
        if (vals) {
            stageStats[stageName(i)] = {
                count: count || 0,
                p50_ms: vals.med || 0,
                p95_ms: vals['p(95)'] || 0,
                p99_ms: vals['p(99)'] || 0,
            };
        }
    });
    const rampVals = data.metrics['ramp_latency_ms']?.values;
    const rampBlock = rampVals && rampFirst >= 0 ? {
        stages: Array.from(rampStages).map(stageName),
        window_sec: [stageBounds[rampFirst], stageBounds[rampLast] + parseFloat(stages[rampLast].duration)],
        count: data.metrics['ramp_requests']?.values?.count || 0,
        p50_ms: rampVals.med || 0,
        p95_ms: rampVals['p(95)'] || 0,
        p99_ms: rampVals['p(99)'] || 0,
    } : null;

    const summary = {
        scenario: scenario,
        run_id: parseInt(run),
        workload: 'clarknet_replay',
        timestamp: new Date().toISOString(),
        duration_sec: stages.length * 30,
        metrics: {
            p50_latency_ms: data.metrics.http_req_duration?.['p(50)'] || 0,
            p95_latency_ms: data.metrics.http_req_duration?.['p(95)'] || 0,
            p99_latency_ms: data.metrics.http_req_duration?.['p(99)'] || 0,
            error_rate: data.metrics.errors?.rate || 0,
            total_requests: data.metrics.http_reqs?.count || 0,
            actual_rps: data.metrics.http_reqs?.rate || 0,
            slo_violations: data.metrics.slo_violations?.count || 0,
            app_duration_avg_ms: data.metrics.app_duration_ms?.avg || 0,
            app_duration_p50_ms: data.metrics.app_duration_ms?.['p(50)'] || 0,
            app_duration_p95_ms: data.metrics.app_duration_ms?.['p(95)'] || 0,
            app_duration_serverless_avg_ms: data.metrics.app_duration_serverless_ms?.avg || 0,
            app_duration_serverless_p95_ms: data.metrics.app_duration_serverless_ms?.['p(95)'] || 0,
            app_duration_k8s_avg_ms: data.metrics.app_duration_k8s_ms?.avg || 0,
        },
    };
    if (Object.keys(stageStats).length) {
        summary.stages = stageStats;
    }
    if (rampBlock) {
        summary.ramp = rampBlock;
    }

    const outDir = __ENV.RESULTS_DIR || 'results/load-tests';

    return {
        [`${outDir}/clarknet_replay_${scenario}_run${run}_${timestamp}.json`]: JSON.stringify(data, null, 2),
        stdout: JSON.stringify(summary, null, 2),
    };
}
